
create extension if not exists pgcrypto;
create table public.farms(id uuid primary key default gen_random_uuid(),name text not null,hectares numeric(12,2) default 0,animal_types text,location text,created_at timestamptz default now());
create table public.workers(id uuid primary key default gen_random_uuid(),farm_id uuid not null references farms on delete cascade,full_name text not null,id_number text,mobile text,residence text,start_date date,salary numeric(12,2),leave_balance numeric(8,2) default 0);
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text,role text not null default 'worker' check(role in('admin','foreman','worker')),farm_id uuid references farms,worker_id uuid references workers);
create table public.leave_requests(id uuid primary key default gen_random_uuid(),worker_id uuid references workers,farm_id uuid references farms,start_date date,end_date date,reason text,status text default 'pending',created_at timestamptz default now());
create table public.worker_records(id uuid primary key default gen_random_uuid(),worker_id uuid references workers,farm_id uuid references farms,record_type text,record_date date,notes text);
create table public.worker_documents(id uuid primary key default gen_random_uuid(),worker_id uuid references workers,farm_id uuid references farms,document_type text,document_month text,amount numeric,description text,storage_path text);
create table public.camps(id uuid primary key default gen_random_uuid(),farm_id uuid references farms,name text,hectares numeric default 0,notes jsonb default '[]');
create table public.livestock(id uuid primary key default gen_random_uuid(),camp_id uuid unique references camps on delete cascade,sheep_rams int default 0,sheep_ewes int default 0,sheep_lambs int default 0,cattle_bulls int default 0,cattle_cows int default 0,cattle_calves int default 0);
create table public.camp_documents(id uuid primary key default gen_random_uuid(),camp_id uuid references camps,farm_id uuid references farms,description text,storage_path text);
create table public.vehicles(id uuid primary key default gen_random_uuid(),farm_id uuid references farms,description text,registration text,engine_number text,licence_expiry date,mileage bigint default 0);
create table public.job_cards(id uuid primary key default gen_random_uuid(),vehicle_id uuid references vehicles,farm_id uuid references farms,job_date date,mileage bigint,description text,cost numeric,storage_path text);
create table public.stock_items(id uuid primary key default gen_random_uuid(),farm_id uuid references farms,category text check(category in('tools','feed')),item_name text,quantity numeric default 0,unit text);
create table public.purchase_requests(id uuid primary key default gen_random_uuid(),farm_id uuid references farms,requested_by uuid references auth.users,description text,quantity numeric,estimated_cost numeric,reason text,status text default 'pending' check(status in('pending','approved','declined')),reviewed_by uuid references auth.users,reviewed_at timestamptz default now());
create table public.finance_transactions(id uuid primary key default gen_random_uuid(),farm_id uuid references farms,transaction_type text check(transaction_type in('income','expense')),description text,amount numeric,transaction_date date,storage_path text,created_by uuid references auth.users);
create table public.tasks(id uuid primary key default gen_random_uuid(),farm_id uuid references farms,worker_id uuid references workers,title text,description text,due_date date,status text default 'open',completed_at timestamptz,created_by uuid references auth.users);
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid()$$;
create or replace function public.my_farm() returns uuid language sql stable security definer set search_path=public as $$select farm_id from profiles where id=auth.uid()$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce(my_role()='admin',false)$$;
create or replace function public.my_worker() returns uuid language sql stable security definer set search_path=public as $$select worker_id from profiles where id=auth.uid()$$;
alter table farms enable row level security;
alter table profiles enable row level security;
do $$declare t text;begin foreach t in array array['workers','leave_requests','worker_records','worker_documents','camps','livestock','camp_documents','vehicles','job_cards','stock_items','purchase_requests','finance_transactions','tasks'] loop execute format('alter table %I enable row level security',t);end loop;end$$;
create policy farm_read on farms for select using(is_admin() or id=my_farm());
create policy farm_admin on farms for all using(is_admin()) with check(is_admin());
create policy profile_read on profiles for select using(is_admin() or id=auth.uid() or (my_role()='foreman' and farm_id=my_farm()));
create policy profile_admin on profiles for all using(is_admin()) with check(is_admin());
-- Staff records are visible only to admin and same-farm foreman; worker's own row is separately allowed.
create policy workers_manager on workers for all using(is_admin() or (my_role()='foreman' and farm_id=my_farm())) with check(is_admin() or (my_role()='foreman' and farm_id=my_farm()));
create policy worker_self on workers for select using(id=my_worker());
do $$declare t text;begin foreach t in array array['leave_requests','worker_records','worker_documents','camps','livestock','camp_documents','vehicles','job_cards','stock_items','purchase_requests','finance_transactions','tasks'] loop execute format('create policy manager_scope on %I for all using(is_admin() or (my_role()=''foreman'' and farm_id=my_farm())) with check(is_admin() or (my_role()=''foreman'' and farm_id=my_farm()))',t);end loop;end$$;
create policy own_leave_read on leave_requests for select using(worker_id=my_worker());
create policy own_leave_insert on leave_requests for insert with check(worker_id=my_worker());
create policy own_task_read on tasks for select using(worker_id=my_worker());
create policy own_task_done on tasks for update using(worker_id=my_worker()) with check(worker_id=my_worker());
create policy own_purchase_read on purchase_requests for select using(requested_by=auth.uid());
create policy purchase_request_insert on purchase_requests for insert with check(requested_by=auth.uid());
create policy purchase_admin_review on purchase_requests for update using(is_admin()) with check(is_admin());
insert into storage.buckets(id,name,public) values('private-documents','private-documents',false) on conflict do nothing;
create policy private_docs_read on storage.objects for select to authenticated using(bucket_id='private-documents' and (is_admin() or (storage.foldername(name))[1]=my_farm()::text));
create policy private_docs_insert on storage.objects for insert to authenticated with check(bucket_id='private-documents' and (is_admin() or (storage.foldername(name))[1]=my_farm()::text));
